// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationshipIdentity) predicate.RelationshipIdentity {
	return predicate.RelationshipIdentity(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelationshipIdentity) predicate.RelationshipIdentity {
	return predicate.RelationshipIdentity(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelationshipIdentity) predicate.RelationshipIdentity {
	return predicate.RelationshipIdentity(sql.NotPredicates(p))
}
